public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) return res;
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, res);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int maxLen = 0;
    for (String s : strings) {
        if (s != null && s.length() > maxLen) {
            maxLen = s.length();
        }
    }
    if (maxLen == 0) {
        return 0;
    }
    for (int len = maxLen; len >= 1; len--) {
        java.util.HashSet<String> substrings = new java.util.HashSet<>();
        for (String s : strings) {
            if (s == null || s.length() < len) {
                continue;
            }
            for (int i = 0; i <= s.length() - len; i++) {
                substrings.add(s.substring(i, i + len));
            }
        }
        for (String sub : substrings) {
            if (sub == null) {
                continue;
            }
            if (sub.length() != len) {
                continue;
            }
            if (substrings.contains(sub)) {
                return len;
            }
            String rev = new StringBuilder(sub).reverse().toString();
            if (substrings.contains(rev)) {
                return len;
            }
        }
    }
    return 0;
}

