public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    int[] freq = new int[26];
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c < 'a' || c > 'z') {
            // If the string may contain non-lowercase letters, handle them by ignoring or throwing an exception.
            // Here we simply ignore them.
            continue;
        }
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder(n);
    int remaining = n;
    while (remaining > 0) {
        // Ascending pass: pick smallest available characters
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest available characters
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[i] will hold all possible sums achievable with i elements
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using the same element twice
        for (int size = n - 1; size >= 1; size--) {
            for (int sum : dp[size - 1]) {
                dp[size].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
