}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        return false;
    }
    if (k <= 0) {
        return true; // every empty string is considered present
    }
    int n = s.length();
    // If the string is shorter than the number of possible codes, impossible
    if (n < (1 << k)) {
        return false;
    }
    int total = 1 << k;          // number of distinct binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;        // keep only k bits
    int code = 0;
    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[code] = true;
        }
    }
    for (boolean present : seen) {
        if (!present) {
            return false;
        }
    }
    return true;
}

