    }
    int insertions = 0;
    int balance = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // need an opening bracket before this ')'
                insertions++;
            } else {
                balance--; // match with an existing '('
            }
        } else {
            // invalid character, ignore or throw exception
            // Here we choose to ignore to keep method robust
        }
    }
    // any remaining unmatched '(' need a closing ')'
    insertions += balance;
    return insertions;
}

