}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // 50 is enough for k up to Integer.MAX_VALUE
    int size = 0;
    fib[size++] = 1;
    fib[size++] = 1;
    while (true) {
        long next = (long) fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = (int) next;
    }
    // Greedy subtraction from largest to smallest
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    // large is in descending order, reverse it to ascending
    Collections.reverse(large);
    List<Integer> allFactors = new ArrayList<>(small);
    allFactors.addAll(large);
    if (k > allFactors.size()) {
        return -1;
    }
    return allFactors.get(k - 1);
}

public String makeGood(String s) {
