private static int dfs(int mask, int lastIndex, int[] A, java.util.Map<Long, Integer> memo) {
    int n = A.length;
    if (mask == (1 << n) - 1) return 1;
    long key = (((long)mask) << 32) | (lastIndex + 1);
    Integer cached = memo.get(key);
    if (cached != null) return cached;
    int total = 0;
    for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) != 0) continue;
