        if (lastIndex == -1 || isPerfectSquare(A[lastIndex] + A[i])) {
            total += dfs(mask | (1 << i), i, A, memo);
        }
    }
    memo.put(key, total);
    return total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int k = 0; k <= m + n - 2; k++) {
        if (k % 2 == 0) {
            int i = Math.min(k, m - 1);
            int j = k - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(k, n - 1);
            int i = k - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    char[][] pairs = {{'0','0'},{'1','1'},{'8','8'},{'6','9'},{'9','6'}};
    char[] middle = {'0','1','8'};
    char[] leftDigits = {'0','1','8','6','9'};
    char[] rightDigits = {'0','1','8','9','6'};
    // recursion
    char[] arr = new char[n];
    build(0, n-1, arr, result, pairs, middle);
    return result;
}

private static void build(int l, int r, char[] arr, List<String> result, char[][] pairs, char[] middle) {
    if (l > r) {
        result.add(new String(arr));
        return;
    }
    if (l == r) {
        for (char c : middle) {
            arr[l] = c;
            result.add(new String(arr));
        }
        return;
    }
    for (int i=0; i<pairs.length; i++) {
        char left = pairs[i][0];
        char right = pairs[i][1];
        if (l == 0 && left == '0' && arr.length > 1) continue; // leading zero not allowed
        arr[l] = left;
        arr[r] = right;
        build(l+1, r-1, arr, result, pairs, middle);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check that all points are distinct
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute twice the signed area of the triangle
    int area = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    if (n <= 0) return res;
    int curr = 1;
    while (curr <= n) {
        res.add(curr);
        if ((long)curr * 10 <= n) {
            curr *= 10;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr++;
        }
    }
    return res;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize with a large number (n+1 is safe as the maximum needed is n)
    for (int i = 1; i <= n; i++) {
        dp[i] = n + 1;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());
    return result.toString();
}
